"""Original explanatory diagrams. No measured or calculated data are plotted."""
def materials(lang):
 ru=lang=='ru'
 def tr(r,e):return r if ru else e
 def octa(x,y,c):
  return f'<g transform="translate({x} {y})"><path d="M0 -30 30 0 0 30 -30 0Z" fill="{c}" fill-opacity=".13" stroke="{c}"/><path d="M0 -30 12 -8 30 0 12 8 0 30 -12 8 -30 0 -12 -8Z M-30 0 30 0 M0 -30 0 30 M-12 -8 12 8 M12 -8 -12 8" fill="none" stroke="{c}" stroke-opacity=".7"/><circle r="4" fill="{c}"/></g>'
 rows=[]
 for layer,formula,color,heading,desc in [
  (False,'SrIrO₃','var(--diagram-blue)' ,tr('Трёхмерная сеть · полуметалл','3D network · semimetal'),tr('Октаэдры IrO₆ соединены в трёх направлениях. Электронные и дырочные состояния участвуют в проводимости.','IrO₆ octahedra connect in three dimensions. Both electron and hole states contribute to transport.')),
  (True,'Sr₂IrO₄','var(--diagram-purple)' ,tr('Слоистая структура · антиферромагнетик','Layered structure · antiferromagnet'),tr('Слои октаэдров разделены прослойками SrO. Спин-орбитальное взаимодействие и электронные корреляции формируют моттовское состояние.','Octahedral layers are separated by SrO layers. Spin–orbit coupling and electron correlations produce a Mott state.'))]:
  points=[(65+60*j,50+60*i) for i in range(2) for j in range(3)] if not layer else [(65+60*j,42+80*i) for i in range(2) for j in range(3)]
  net=''.join(octa(x,y,color) for x,y in points)
  if not layer:net='<g opacity=".35" transform="translate(20 -12)">'+net+'</g>'+net
  else:net+='<path d="M30 82H225" stroke="currentColor" stroke-dasharray="3 6" opacity=".35"/><text x="242" y="87" fill="currentColor" font-size="11">SrO</text>'
  crystal=f'<svg viewBox="0 0 300 165" role="img" aria-label="{tr("Схема связности октаэдров","Octahedral connectivity schematic")} {formula}">{net}</svg>'
  curves=('<path d="M40 60 Q95 195 150 60 M150 155 Q205 20 260 155"/>' if not layer else '<path d="M40 50 Q150 120 260 50 M40 165 Q150 100 260 165"/>')
  band=f'<svg viewBox="0 0 300 200" role="img" aria-label="{tr("Схема перекрытия зон","Schematic band overlap") if not layer else tr("Схема энергетической щели","Schematic energy gap")}"><path d="M25 15V180H275" fill="none" stroke="currentColor" opacity=".45"/><text x="8" y="18" fill="currentColor" font-size="12">E</text><text x="278" y="184" fill="currentColor" font-size="12">k</text><path d="M25 108H270" stroke="currentColor" stroke-dasharray="4 5" opacity=".4"/><text x="263" y="101" fill="currentColor" font-size="11">E<tspan baseline-shift="sub">F</tspan></text><g fill="none" stroke="{color}" stroke-width="2.5">{curves}</g></svg>'
  rows.append(f'<article class="material"><div class="material-heading"><h3>{formula}</h3><span>{heading}</span></div><div class="material-visuals">{crystal}{band}</div><p>{desc}</p></article>')
 return '<div class="materials">'+''.join(rows)+'</div><p class="figure-key">'+tr('Схемы показывают связность октаэдров и различие электронных состояний. Повороты октаэдров и атомы Sr опущены; линии E(k) иллюстративные.','Schematics show octahedral connectivity and contrasting electronic states. Octahedral rotations and Sr atoms are omitted; E(k) curves are illustrative.')+'</p>'

def devices(lang,a):
 ru=lang=='ru'
 def tr(r,e):return r if ru else e
 stack=f'''<svg viewBox="0 0 340 180" role="img" aria-label="{tr('Схема устройства: зарядовый ток в SrIrO₃ создаёт спиновый ток, действующий на магнитный слой SrRuO₃','Device schematic: charge current in SrIrO₃ generates a spin current acting on magnetic SrRuO₃')}"><rect x="30" y="35" width="280" height="48" rx="4" fill="var(--diagram-purple)" fill-opacity=".18" stroke="var(--diagram-purple)"/><rect x="30" y="88" width="280" height="48" rx="4" fill="var(--diagram-blue)" fill-opacity=".18" stroke="var(--diagram-blue)"/><g fill="currentColor" font-size="15"><text x="45" y="65">SrRuO₃</text><text x="45" y="118">SrIrO₃</text><text x="225" y="65">M ↑ / ↓</text></g><path d="M170 120V58m-6 8 6-8 6 8M45 157H290m-8-6 8 6-8 6" fill="none" stroke="currentColor" stroke-width="2"/><text x="182" y="104" fill="currentColor" font-size="12">J<tspan baseline-shift="sub">s</tspan></text><text x="145" y="176" fill="currentColor" font-size="12">{tr('Зарядовый ток','Charge current')}</text></svg>'''
 memory=f'''<svg viewBox="0 0 340 180" role="img" aria-label="{tr('Два состояния сопротивления в экспериментальной памяти на Sr₂IrO₄ с галлием','Two resistance states of experimental Ga-doped Sr₂IrO₄ memory')}"><rect x="20" y="30" width="125" height="105" rx="10" fill="var(--diagram-purple)" fill-opacity=".12" stroke="var(--diagram-purple)"/><rect x="195" y="30" width="125" height="105" rx="10" fill="var(--diagram-blue)" fill-opacity=".12" stroke="var(--diagram-blue)"/><g fill="currentColor" text-anchor="middle"><text x="82" y="82" font-size="34">0</text><text x="258" y="82" font-size="34">1</text><text x="82" y="113" font-size="12">R<tspan baseline-shift="sub">low</tspan></text><text x="258" y="113" font-size="12">R<tspan baseline-shift="sub">high</tspan></text><text x="170" y="91" font-size="24">⇄</text><text x="170" y="166" font-size="12">{tr('Запись магнитным полем · 10 К','Magnetic-field writing · 10 K')}</text></g></svg>'''
 return f'''<p class="section-intro">{tr('В спинтронике информацию хранят в магнитном состоянии, а электрический ток используют для записи и считывания. Иридаты интересны здесь сильной связью спина с орбитальным движением электронов. Уже есть экспериментальные устройства, в которых эта связь работает на практике.','Spintronic devices store information in magnetic states and use electric currents to write or read them. Iridates offer strong coupling between spin and orbital motion, with experimental devices already demonstrating its uses.')}</p><div class="device-grid"><article>{stack}<h3>{tr('Переключение намагниченности током','Current-driven magnetic switching')}</h3><p>{tr('В двухслойной структуре SrIrO₃/SrRuO₃ ток в иридате за счёт спин-орбитального взаимодействия переключает намагниченность соседнего слоя при низкой температуре. Такой механизм исследуют для магнитной памяти.','In a SrIrO₃/SrRuO₃ bilayer, current in the iridate generates a spin–orbit torque that switches the neighbouring magnetic layer at low temperature. This mechanism is being explored for magnetic memory.')}</p>{a('https://www.nature.com/articles/s41565-019-0534-7','Liu et al. · Nature Nanotechnology, 2019 ↗')}</article><article>{memory}<h3>{tr('Память на антиферромагнетике','Antiferromagnetic memory')}</h3><p>{tr('В Sr₂IrO₄ с 1 % галлия показаны два состояния сопротивления, сохраняющиеся после снятия магнитного поля. Запись и считывание продемонстрированы при 10 К.','Sr₂IrO₄ with 1% Ga supports two resistance states that remain after the magnetic field is removed. Writing and readout were demonstrated at 10 K.')}</p>{a('https://www.nature.com/articles/s41467-019-10299-6','Wang et al. · Nature Communications, 2019 ↗')}</article></div><p class="figure-key">{tr('Примеры работ других исследовательских групп. На схемах показан принцип действия экспериментальных прототипов.','Examples from other research groups. Diagrams illustrate the operating principles of experimental prototypes.')}</p>'''
